def canvas_widget(window=None):
    window = window or krita.instance().activeWindow()
    qwindow = _call(window, "qwindow", None) if window else None
    if qwindow is not None and hasattr(qwindow, "findChild"):
        widget = qwindow.findChild(QWidget, "view_0")
        if widget: return widget
    return krita.active_canvas_widget()


def install_canvas_hook(callback=None, widget=None):
    widget = widget or canvas_widget()
    if widget is None: raise RuntimeError("Krita did not expose an active canvas widget")
    hook = CanvasInputInterceptor(widget, callback); _CANVAS_HOOKS.append(hook); return hook
def remove_canvas_hook(hook=None):
    for item in list(_CANVAS_HOOKS) if hook is None else [hook]:
        item.detach()
        if item in _CANVAS_HOOKS: _CANVAS_HOOKS.remove(item)


